        FROM patient
        WHERE
            is_consent_9nu0 = false
        ) AS t1oo UNION SELECT ndoo.patient_id AS patient_id 
FROM (
        SELECT
            patient_id
        FROM patient
        WHERE
            is_national_data_opted_in = false
        ) AS ndoo;

