FROM ehrql_20261014_1922_e9a0681f0d7d_tmp_27 LEFT OUTER JOIN ehrql_20261014_1922_e9a0681f0d7d_tmp_23 ON ehrql_20261014_1922_e9a0681f0d7d_tmp_23.patient_id = ehrql_20261014_1922_e9a0681f0d7d_tmp_27.patient_id LEFT OUTER JOIN (
