CREATE TABLE ehrql_20261014_1922_e9a0681f0d7d_tmp_163 AS SELECT anon_1.patient_id AS patient_id, anon_1.snomedct_code AS snomedct_code 
FROM (SELECT clinical_events.patient_id AS patient_id, clinical_events.snomedct_code AS snomedct_code, row_number() OVER (PARTITION BY clinical_events.patient_id ORDER BY clinical_events.date DESC, clinical_events.snomedct_code DESC) AS anon_2 
FROM (
        SELECT
            patient_id,
            CAST(effective_datetime AS date) as date,
            CAST(snomed_concept_id AS varchar) AS snomedct_code,
            CAST(numeric_value AS real) AS numeric_value,
            consultation_id
        FROM observation
        ) AS clinical_events 
WHERE clinical_events.snomedct_code IN (SELECT ehrql_20261014_1922_e9a0681f0d7d_inline_data_162.value 
FROM ehrql_20261014_1922_e9a0681f0d7d_inline_data_162) AND clinical_events.date <= '2024-06-01' AND clinical_events.patient_id IN (SELECT ehrql_20261014_1922_e9a0681f0d7d_tmp_159.patient_id 
FROM ehrql_20261014_1922_e9a0681f0d7d_tmp_159)) AS anon_1 
WHERE anon_1.anon_2 = 1;

