CREATE TABLE ehrql_20261014_1922_e9a0681f0d7d_tmp_200 AS SELECT clinical_events.patient_id AS patient_id, clinical_events.consultation_id AS value 
FROM (
        SELECT
            patient_id,
            CAST(effective_datetime AS date) as date,
            CAST(snomed_concept_id AS varchar) AS snomedct_code,
            CAST(numeric_value AS real) AS numeric_value,
            consultation_id
        FROM observation
        ) AS clinical_events 
WHERE clinical_events.snomedct_code IN ('1577041000000109', '983341000000102', '2129921000000100') AND clinical_events.consultation_id IS NOT NULL;

-- Run query 416 / 690
CREATE TABLE ehrql_20261014_1922_e9a0681f0d7d_tmp_201 AS SELECT DISTINCT clinical_events.patient_id AS patient_id 
FROM (
        SELECT
            patient_id,
            CAST(effective_datetime AS date) as date,
            CAST(snomed_concept_id AS varchar) AS snomedct_code,
            CAST(numeric_value AS real) AS numeric_value,
            consultation_id
        FROM observation
        ) AS clinical_events 
WHERE clinical_events.date >= '2024-08-01' AND clinical_events.date <= '2024-08-31' AND clinical_events.consultation_id IN (SELECT ehrql_20261014_1922_e9a0681f0d7d_tmp_200.value 
FROM ehrql_20261014_1922_e9a0681f0d7d_tmp_200 
WHERE ehrql_20261014_1922_e9a0681f0d7d_tmp_200.patient_id = clinical_events.patient_id) AND clinical_events.snomedct_code IN ('1577041000000109', '983341000000102', '2129921000000100');

-- Run query 417 / 690
CREATE TABLE ehrql_20261014_1922_e9a0681f0d7d_tmp_199 AS SELECT anon_1.patient_id AS patient_id 
FROM (SELECT practice_registrations.patient_id AS patient_id, row_number() OVER (PARTITION BY practice_registrations.patient_id ORDER BY practice_registrations.start_date DESC) AS anon_2 
FROM (
        SELECT
            patient_id AS patient_id,
            CAST(registration_start_datetime AS date) AS start_date,
            CAST(registration_end_datetime AS date) AS end_date
        FROM patient
        ) AS practice_registrations 
WHERE practice_registrations.start_date <= '2024-08-31' AND (practice_registrations.end_date >= '2024-08-31' OR practice_registrations.end_date IS NULL)) AS anon_1 
WHERE anon_1.anon_2 = 1;

