FROM ehrql_20261014_1922_e9a0681f0d7d_tmp_203 LEFT OUTER JOIN ehrql_20261014_1922_e9a0681f0d7d_tmp_199 ON ehrql_20261014_1922_e9a0681f0d7d_tmp_199.patient_id = ehrql_20261014_1922_e9a0681f0d7d_tmp_203.patient_id LEFT OUTER JOIN (
        SELECT
            patient_id AS patient_id,
            CAST(date_of_birth AS date) AS date_of_birth,
            CASE
                WHEN sex = 'M' THEN 'male'
                WHEN sex = 'F' THEN 'female'
                WHEN sex = 'I' THEN 'intersex'
