-- Run query 529 / 690
CREATE TABLE ehrql_20261014_1922_e9a0681f0d7d_tmp_249 AS SELECT anon_1.patient_id AS patient_id, anon_1.imd_rounded_2019 AS imd_rounded_2019, anon_1.msoa_code_2011 AS msoa_code_2011 
FROM (SELECT addresses.patient_id AS patient_id, addresses.imd_rounded_2019 AS imd_rounded_2019, addresses.msoa_code_2011 AS msoa_code_2011, row_number() OVER (PARTITION BY addresses.patient_id ORDER BY addresses.start_date DESC, addresses.imd_rounded_2019 DESC, addresses.msoa_code_2011 DESC) AS anon_2 
FROM (
        SELECT
            patient_id AS patient_id,
            CAST(registration_start_datetime AS date) AS start_date,
            CAST(registration_end_datetime AS date) AS end_date,
            CAST(imd_rounded_2011 AS int) AS imd_rounded_2019,
            CAST(imd_rounded_2021 AS int) AS imd_rounded_2025,
            index_of_multiple_deprivation_decile_2011 AS imd_decile_2019,
            index_of_multiple_deprivation_decile_2021 AS imd_decile_2025,
            middle_level_super_output_area_code_2011 AS msoa_code_2011,
            middle_level_super_output_area_code_2021 AS msoa_code_2021
        FROM patient
        ) AS addresses 
WHERE addresses.start_date <= '2024-10-01' AND (addresses.end_date >= '2024-10-01' OR CASE WHEN (addresses.end_date < '2024-10-01') THEN true WHEN (addresses.end_date >= '2024-10-01') THEN false END IS NULL) AND addresses.patient_id IN (SELECT ehrql_20261014_1922_e9a0681f0d7d_tmp_247.patient_id 
FROM ehrql_20261014_1922_e9a0681f0d7d_tmp_247)) AS anon_1 
WHERE anon_1.anon_2 = 1;

-- Run query 530 / 690
CREATE TABLE ehrql_20261014_1922_e9a0681f0d7d_tmp_248 AS SELECT clinical_events.patient_id AS patient_id, count('*') AS value 
FROM (
        SELECT
            patient_id,
            CAST(effective_datetime AS date) as date,
            CAST(snomed_concept_id AS varchar) AS snomedct_code,
            CAST(numeric_value AS real) AS numeric_value,
            consultation_id
        FROM observation
        ) AS clinical_events 
WHERE clinical_events.date >= '2024-10-01' AND clinical_events.date <= '2024-10-31' AND clinical_events.consultation_id IN (SELECT ehrql_20261014_1922_e9a0681f0d7d_tmp_244.value 
FROM ehrql_20261014_1922_e9a0681f0d7d_tmp_244 
WHERE ehrql_20261014_1922_e9a0681f0d7d_tmp_244.patient_id = clinical_events.patient_id) AND clinical_events.snomedct_code IN ('1577041000000109') AND clinical_events.patient_id IN (SELECT ehrql_20261014_1922_e9a0681f0d7d_tmp_247.patient_id 
FROM ehrql_20261014_1922_e9a0681f0d7d_tmp_247) GROUP BY clinical_events.patient_id;

