CREATE TABLE ehrql_20261014_1922_e9a0681f0d7d_tmp_288 AS SELECT clinical_events.patient_id AS patient_id, clinical_events.consultation_id AS value 
FROM (
        SELECT
            patient_id,
            CAST(effective_datetime AS date) as date,
            CAST(snomed_concept_id AS varchar) AS snomedct_code,
            CAST(numeric_value AS real) AS numeric_value,
            consultation_id
        FROM observation
        ) AS clinical_events 
WHERE clinical_events.snomedct_code IN ('1577041000000109', '983341000000102', '2129921000000100') AND clinical_events.consultation_id IS NOT NULL;

-- Run query 600 / 690
CREATE TABLE ehrql_20261014_1922_e9a0681f0d7d_tmp_289 AS SELECT DISTINCT clinical_events.patient_id AS patient_id 
FROM (
        SELECT
            patient_id,
            CAST(effective_datetime AS date) as date,
            CAST(snomed_concept_id AS varchar) AS snomedct_code,
            CAST(numeric_value AS real) AS numeric_value,
            consultation_id
        FROM observation
        ) AS clinical_events 
WHERE clinical_events.date >= '2024-12-01' AND clinical_events.date <= '2024-12-31' AND clinical_events.consultation_id IN (SELECT ehrql_20261014_1922_e9a0681f0d7d_tmp_288.value 
