FROM ehrql_20261014_1922_e9a0681f0d7d_tmp_291 LEFT OUTER JOIN ehrql_20261014_1922_e9a0681f0d7d_tmp_287 ON ehrql_20261014_1922_e9a0681f0d7d_tmp_287.patient_id = ehrql_20261014_1922_e9a0681f0d7d_tmp_291.patient_id LEFT OUTER JOIN (
        SELECT
            patient_id AS patient_id,
            CAST(date_of_birth AS date) AS date_of_birth,
            CASE
                WHEN sex = 'M' THEN 'male'
